      number: 10,
      book: "Faith (Kitab al-Iman)",
      ar: "الْمُسْلِمُ مَنْ سَلِمَ الْمُسْلِمُونَ مِنْ لِسَانِهِ وَيَدِهِ، وَالْمُهَاجِرُ مَنْ هَجَرَ مَا نَهَى اللَّهُ عَنْهُ.",
      en: "The true Muslim is the one from whose tongue and hand other Muslims are safe, and the true emigrant (Muhajir) is the one who abandons that which Allah has forbidden.",
