      collection: "Sahih al-Bukhari",
      number: 5971,
      book: "Good Manners (Kitab al-Adab)",
      ar: "جَاءَ رَجُلٌ إِلَى رَسُولِ اللَّهِ ﷺ فَقَالَ: يَا رَسُولَ اللَّهِ، مَنْ أَحَقُّ النَّاسِ بِحُسْنِ صَحَابَتِي؟ قَالَ: «أُمُّكَ». قَالَ: ثُمَّ مَنْ؟ قَالَ: «ثُمَّ أُمُّكَ». قَالَ: ثُمَّ مَنْ؟ قَالَ: «ثُمَّ أُمُّكَ». قَالَ: ثُمَّ مَنْ؟ قَالَ: «ثُمَّ أَبُوكَ».",
      en: "A man came to the Messenger of Allah ﷺ and asked: 'O Messenger of Allah, who among people is most deserving of my finest companionship?' He replied: 'Your mother.' The man asked: 'Then who?' He replied: 'Your mother.' The man asked: 'Then who?' He replied: 'Your mother.' The man asked: 'Then who?' He replied: 'Then your father.'",
      ur: "ایک شخص رسول اللہ ﷺ کی خدمت میں حاضر ہوا اور عرض کی: یا رسول اللہ! لوگوں میں میرے حسن سلوک کا سب سے زیادہ حقدار کون ہے؟ آپ ﷺ نے فرمایا: 'تمہاری ماں۔' اس نے پوچھا: پھر کون؟ فرمایا: 'تمہاری ماں۔' اس نے پوچھا: پھر کون؟ فرمایا: 'تمہاری ماں۔' اس نے پوچھا: پھر کون؟ فرمایا: 'پھر تمہارا باپ۔'",
      narrator: "Abu Hurairah (RA)",
      grade: "Sahih (Authentic)",
      gradeScholar: "Muttafaqun 'Alayh (Bukhari & Muslim)",
      topic: "Family"
