      ar: "كَلِمَتَانِ خَفِيفَتَانِ عَلَى اللِّسَانِ، ثَقِيلَتَانِ فِي الْمِيزَانِ، حَبِيبَتَانِ إِلَى الرَّحْمَنِ: سُبْحَانَ اللَّهِ وَبِحَمْدِهِ، سُبْحَانَ اللَّهِ الْعَظِيمِ.",
      en: "Two statements are light on the tongue, heavy on the balance, and beloved to the Most Merciful: 'Subhanallahi wa bihamdihi' (Glory be to Allah and His praise), and 'Subhanallahil-'Azeem' (Glory be to Allah, the Supreme).",
