      ar: "إِيَّاكُمْ وَالظَّنَّ فَإِنَّ الظَّنَّ أَكْذَبُ الْحَدِيثِ، وَلاَ تَحَسَّسُوا، وَلاَ تَجَسَّسُوا، وَلاَ تَنَافَسُوا، وَلاَ تَحَاسَدُوا، وَلاَ تَبَاغَضُوا، وَلاَ تَدَابَرُوا، وَكُونُوا عِبَادَ اللَّهِ إِخْوَانًا.",
      en: "Beware of suspicion, for suspicion is the most deceitful of speech. Do not pry, do not spy upon one another, do not outbid one another deceitfully, do not envy one another, do not hate one another, do not turn away from one another, and be servants of Allah as brothers.",
      ur: "بدگمانی سے بچو کیونکہ بدگمانی سب سے جھوٹی بات ہے۔ کسی کے عیوب مت ٹٹولو، نہ جاسوسی کرو، نہ ایک دوسرے کو نیچا دکھانے کے لیے دام بڑھاؤ، نہ آپس میں حسد کرو، نہ بغض رکھو، نہ ایک دوسرے سے قطع تعلق کرو، اور اللہ کے بندے بن کر بھائی بھائی ہو جاؤ۔",
