      number: 50,
      book: "Faith (Kitab al-Iman)",
      ar: "قَالَ: يَا مُحَمَّدُ، أَخْبِرْنِي عَنِ الإِسْلاَمِ... قَالَ: فَأَخْبِرْنِي عَنِ الإِيمَانِ... قَالَ: فَأَخْبِرْنِي عَنِ الإِحْسَانِ، قَالَ: «أَنْ تَعْبُدَ اللَّهَ كَأَنَّكَ تَرَاهُ، فَإِنْ لَمْ تَكُنْ تَرَاهُ فَإِنَّهُ يَرَاكَ».",
      en: "Gabriel said: 'Inform me about Ihsan (excellence).' The Prophet ﷺ replied: 'It is to worship Allah as though you see Him, for though you do not see Him, He truly sees you.'",
