      ar: "بَيْنَمَا كَلْبٌ يُطِيفُ بِرَكِيَّةٍ كَادَ يَقْتُلُهُ الْعَطَشُ، إِذْ رَأَتْهُ بَغِيٌّ مِنْ بَغَايَا بَنِي إِسْرَائِيلَ، فَنَزَعَتْ مُوقَهَا فَاسْتَقَتْ لَهُ بِهِ فَسَقَتْهُ، فَغُفِرَ لَهَا بِهِ.",
      en: "While a dog was circling a well on the verge of dying of thirst, an unchaste woman from the Children of Israel saw it, removed her shoe, drew water with it, and gave the dog to drink. For that act of mercy, Allah forgave her sins.",
