      number: 2513,
      book: "Asceticism",
      ar: "انْظُرُوا إِلَى مَنْ هُوَ أَسْفَلَ مِنْكُمْ، وَلَا تَنْظُرُوا إِلَى مَنْ هُوَ فَوْقَكُمْ، فَهُوَ أَجْدَرُ أَنْ لَا تَزْدَرُوا نِعْمَةَ اللَّهِ عَلَيْكُمْ.",
      en: "Look at those who have less than you in material worldly terms, and do not look at those who possess more than you, for that is more fitting so that you do not belittle or disparage the blessings of Allah upon you.",
