      collection: "Sahih al-Bukhari",
      number: 2442,
      book: "Injustices & Usurpation",
      ar: "انْصُرْ أَخَاكَ ظَالِمًا أَوْ مَظْلُومًا. قَالُوا: يَا رَسُولَ اللَّهِ، هَذَا نَنْصُرُهُ مَظْلُومًا، فَكَيْفَ نَنْصُرُهُ ظَالِمًا؟ قَالَ: «تَأْخُذُ فَوْقَ يَدَيْهِ فَتَمْنَعُهُ مِنَ الظُّلْمِ، فَإِنَّ ذَلِكَ نَصْرُهُ».",
      en: "Help your brother whether he is an oppressor or is being oppressed. The companions asked: 'O Messenger of Allah, we help him when he is oppressed, but how do we help him if he is an oppressor?' The Prophet replied: 'By seizing his hands and restraining him from committing oppression; that is truly helping him.'",
