      collection: "Sahih Muslim",
      number: 2607,
      book: "Virtues",
      ar: "الْمُؤْمِنُ الْقَوِيُّ خَيْرٌ وَأَحَبُّ إِلَى اللَّهِ مِنَ الْمُؤْمِنِ الضَّعِيفِ، وَفِي كُلٍّ خَيْرٌ. احْرِصْ عَلَى مَا يَنْفَعُكَ، وَاسْتَعِنْ بِاللَّهِ وَلَا تَعْجَزْ.",
      en: "The strong believer is better and more beloved to Allah than the weak believer, though there is good in both. Be eager for that which benefits you, seek help from Allah, and do not despair or give up.",
