      collection: "Sahih al-Bukhari",
      number: 6019,
      book: "Good Manners",
      ar: "لَيْسَ الْوَاصِلُ بِالْمُكَافِئِ، وَلَكِنَّ الْوَاصِلَ الَّذِي إِذَا قُطِعَتْ رَحِمُهُ وَصَلَهَا.",
