      ur: "تین خصلتیں ایسی ہیں کہ جس میں وہ ہوں اس نے ایمان کی مٹھاس پا لی: یہ کہ اللہ اور اس کا رسول اسے ہر چیز سے زیادہ محبوب ہوں، اور یہ کہ وہ کسی انسان سے صرف اللہ کے لیے محبت کرے، اور یہ کہ وہ کفر میں واپس جانے کو ایسا ناپسند کرے جیسے آگ میں پھینکے جانے کو ناپسند کرتا ہے۔",
